import { DatePipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { UploadService } from 'src/app/services/emis/upload.service';
import { GrievanceService } from 'src/app/services/grievance.service';
import { SharedService } from 'src/app/services/shared.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import moment from 'moment';
@Component({
  selector: 'app-staff-grievance',
  templateUrl: './staff-grievance.page.html',
  styleUrls: ['./staff-grievance.page.scss'],
})
export class StaffGrievancePage implements OnInit {
  staffInfoForm: FormGroup;
  grievanceForm: FormGroup;
  pipe = new DatePipe('en-US');
  date: string = this.pipe.transform(new Date(), 'yyyy-MM-dd');
  documentArr: any[] = ['GrievanceDoc1'];
  language: string = 'தமிழ்';
  minDate: any = "2018-01-01";
  Lists: any;
  langJson: any;
  submitted: boolean;
  typeActive: boolean;
  teacherId: number;
  school_id: number;
  pageid: any;
  grievanceList: any = [];
  editActive: boolean;
  grievanceListCopy: any = [];
  IndexId: any;
  issuesList: any[];
  noData: boolean;
  blockid: any;
  jsonData: any;
  langToggleActive: boolean = true;
  GrNo: any;
  grievanceTypeLists: any[];
  grievanceCategoryLists: any[];
  statusList: any[];
  editId: number;
  viewDoc1: any;
  viewDoc2: any;
  viewDoc3: any;
  grievanceStatusValue: any;

  constructor(private router: Router, private fb: FormBuilder,
    private route: ActivatedRoute, private alertService: AlertService,
    private grievanceService: GrievanceService,
    private usersessionService: UserSessionService, private alertController: AlertController,
    private uploadService: UploadService, private sharedService: SharedService) { }

  ngOnInit() {
    this.initialValidator();
  }

  initialValidator() {
    this.staffInfoForm = this.fb.group({
      staffName: [''],
      staffId: [''],
      staffMobile: [''],
      staffDist: [''],
      staffBlock: [''],
      staffDesign: [''],
      staffSchool: [''],
      staffStatus: [''],
      Archive: [''],
    });

    this.grievanceForm = this.fb.group({
      IndexId: [''],
      GrNo: [''],
      TeacherId: [''],
      SchoolKeyId: [''],
      MblNo: ['', Validators.required],
      ActiveStatus: [''],
      GrievanceStatus: ['1'],
      GrievanceUpdatedBy: [''],
      GrievanceUpdatedDate: [''],
      UpdatedRemarks: [''],
      BlkId: [''],

      Department: [''],
      GrievanceLevel: [''],
      GrievanceType: ['', Validators.required],
      GrievanceCategory: ['1', Validators.required],
      GrievanceDate: [''],
      grievancePendays: [''],
      GrievanceDoc1: ['', Validators.required],
      GrievanceDoc2: [''],
      GrievanceDoc3: [''],
      GrievanceDoc4: [''],
      GrievanceDoc5: [''],
      Remarks: ['', Validators.required],
      FileNumber: [''],
      Issue: [''],
      OtherIssue: ['']
    });
  }

  ionViewDidEnter() {
    this.grievanceList = [];
    this.pageid = this.route.snapshot.queryParams.pageid;
    this.teacherId = this.usersessionService.teacher_id();
    this.school_id =this.usersessionService.school_key_id();
    this.blockid = this.usersessionService.district_id() ? this.usersessionService.district_id() : '00';

    this.Lists = this.grievanceService.Lists;
    this.langJson = this.grievanceService.langJson;

    this.langJsonChange();
    this.formChange(1);

    this.getTeacherInfo();

    if (this.pageid == 1) {
      this.getSavedGrievanceData();
    }
  }

  langJsonChange() {
    if (this.language == 'தமிழ்') {
      this.langToggleActive = true;
      this.jsonData = this.langJson.tamil;
    } else {
      this.langToggleActive = false;
      this.jsonData = this.langJson.english;
    }
    this.grievanceTypeLists = this.language == 'English' ? this.Lists.grievanceTypeList : this.Lists.grievanceTypeTamilList;
    this.grievanceCategoryLists = this.language == 'English' ? this.Lists.grievanceCategoryList : this.Lists.grievanceCategoryTamilList;
    let issueList = (this.language == 'English') ? this.Lists.issues : this.Lists.issuesTamilList;
    this.issuesList = issueList.filter(i => i.type == this.grievanceForm.value.GrievanceCategory);
    this.statusList = this.language == 'English' ? this.Lists.grievanceStatus : this.Lists.grievanceStatusTamil;
  }

  formChange(id) {
    if (id == 1) {
      this.grievanceForm.controls['Issue'].setValidators(null);
      this.grievanceForm.controls['OtherIssue'].setValidators(null);
      this.grievanceForm.controls['FileNumber'].setValidators(null);
      this.grievanceForm.controls['GrievanceDate'].setValidators(null);
      this.grievanceForm.controls['GrievanceCategory'].setValue('1');
    }
  }

  getTeacherInfo() {
    this.grievanceService.TeacherDetailsGet(this.teacherId).subscribe(res => {
      if (res.dataStatus) {
        this.grievanceForm.patchValue(res.result[0]);
        this.staffInfoForm.patchValue(res.result[0]);
      }
    })
  }

  calculatePendingDays(event) {
    var date1: any = new Date(moment(event).format('yyyy-MM-DD'));
    var date2: any = new Date(moment(new Date()).format('yyyy-MM-DD'));
    var diffDays: any = Math.floor((date2 - date1) / (1000 * 60 * 60 * 24));
    this.grievanceForm.controls.grievancePendays.setValue(diffDays);
  }

  onSearch(list, event) {
    let searchTerm = event.detail.value.trim();
    this.grievanceList = this.grievanceListCopy[0].filter((item) => {
      return item.GrievanceDate.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.GrNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.dateFormat.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.GrievanceTypeText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.GrievanceCategoryText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.GrievanceStatusText.toLowerCase().includes(searchTerm.toLowerCase());
    });
  }

  onFileNumberUppercase() {
    let fileno = this.grievanceForm.value.FileNumber.toUpperCase();
    this.grievanceForm.controls['FileNumber'].setValue(fileno);
  }

  onChange(id) {
    if (id == 1) {
      if (this.grievanceForm.value.GrievanceType) {
        if (this.grievanceForm.value.GrievanceType == 1) {
          this.typeActive = true;
          this.grievanceForm.controls['GrievanceDate'].setValue(this.date);
          this.grievanceForm.controls['grievancePendays'].setValue('');
          this.grievanceForm.controls['FileNumber'].setValue('');
        } else {
          this.typeActive = false;
          this.grievanceForm.controls['GrievanceDate'].setValue('');
          this.grievanceForm.controls['grievancePendays'].setValue('');
          this.grievanceForm.controls['GrievanceDate'].setValidators(Validators.required);
        }
        this.grievanceForm.controls['GrievanceDate'].updateValueAndValidity();
      }
    }

    if (id == 2) {
      let issueList = (this.language == 'English') ? this.Lists.issues : this.Lists.issuesTamilList;
      this.issuesList = issueList.filter(i => i.type == this.grievanceForm.value.GrievanceCategory);

      this.grievanceForm.controls['Issue'].setValue('');
      this.grievanceForm.controls['OtherIssue'].setValue('');

      if (this.grievanceForm.value.GrievanceCategory == 1 || this.grievanceForm.value.GrievanceCategory == 2) {
        this.grievanceForm.controls['Issue'].setValidators(Validators.required);
      } else {
        this.grievanceForm.controls['Issue'].setValidators(null);
      }
      this.grievanceForm.controls['Issue'].updateValueAndValidity();
    }

    if (id == 3) {
      if (this.grievanceForm.value.Issue == 99) {
        this.grievanceForm.controls['OtherIssue'].setValidators(Validators.required);
      } else {
        this.grievanceForm.controls['OtherIssue'].setValue('');
        this.grievanceForm.controls['OtherIssue'].setValidators(null);
      }
      this.grievanceForm.controls['OtherIssue'].updateValueAndValidity();
    }

  }

  //--------------- Document Upload Code ----------------//

  onSelectFiles(event: any, string) {
    if (event.target.files && event.target.files[0]) {
      var doc_file = event.target.files;
      var fileName = event.target.files[0].name;
      var splittedName = fileName.split(".");
      var fileType = splittedName[(splittedName.length) - 1];
      if (fileType == 'jpeg' || fileType == 'jpg' || fileType == 'png' || fileType == 'pdf') {
        if (event.target.files[0].size <= 5000000) {
          var bucketName = "renewalapplicationemis";
          var filename = splittedName[0];
          var ext = splittedName[1];
          let expiry: number = 300;
          this.uploadService.getSignedUrl(bucketName, ext, filename, expiry).subscribe((result) => {
            if (result) {
              let files: FileList = doc_file;
              let file: File = files[0];
              this.uploadService.uploadFile(result.url, file).subscribe((res) => {
                this.grievanceForm.controls[string].setValue(result.key);
              });
            }
          });
        } else {
          this.alertService.error('File can`t uploaded because file size should not exceed 5MB');
          if (string != 'GrievanceDoc1') {
            let documentArr = this.documentArr.filter(e => e !== string)
            this.documentArr = documentArr;
          }

        }
      }
      else {
        this.alertService.error('File must be a valid format');
        this.grievanceForm.controls[string].setValue(null);
        if (string != 'GrievanceDoc1') {
          let documentArr = this.documentArr.filter(e => e !== string)
          this.documentArr = documentArr;
        }
      }
    }
  }

  getUploadedFiles(id, filename: any) {
    var arr = filename.split(".");
    let url = "https://deka0egrc3bqo.cloudfront.net/" + filename;
    if (id == 1) {
      // this.sharedService.onDownload('Grievance_Document','https://deka0egrc3bqo.cloudfront.net/',filename)
      window.open(url)
    } else {
      if (arr[1] == 'pdf') {
        this.sharedService.onView(2, 2, url)
      } else {
        this.sharedService.onView(1, 2, url)
      }
    }
  }

  addDocument() {
    var docs = ['GrievanceDoc1', 'GrievanceDoc2', 'GrievanceDoc3', 'GrievanceDoc4', 'GrievanceDoc5'];
    for (let i = 0; i < docs.length; i++) {
      if (!(this.documentArr.includes(docs[i]))) {
        this.documentArr.push(docs[i]);
        this.grievanceForm.controls[docs[i]].setValue('');
        break;
      }
    }
  }

  deleteDocumet(formControl) {
    this.documentArr = this.documentArr.filter(item => item !== formControl);
    this.grievanceForm.controls[formControl].setValue('');
  }

  // ------ Raise New Grievance ----------//

  onRaiseNewGrievance() {
    this.editId = 2;
    this.pageid = 2;
    let issueList = (this.language == 'English') ? this.Lists.issues : this.Lists.issuesTamilList;
    this.issuesList = issueList.filter(i => i.type == this.grievanceForm.value.GrievanceCategory);
    this.grievanceForm.reset();
    this.documentArr = ['GrievanceDoc1'];
    this.grievanceForm.controls['GrievanceCategory'].setValue('1');
    this.grievanceForm.controls['GrievanceStatus'].setValue(1);
    this.grievanceForm.controls['MblNo'].setValue(this.staffInfoForm.value.staffMobile);
    this.onChange(2);
  }

  // ------ Save Grievance details ----------//

  onValidateGrievanceForm() {
    this.submitted = true;
    this.grievanceForm.controls['IndexId'].setValue(this.editActive ? this.IndexId : "");
    this.grievanceForm.controls['GrNo'].setValue(this.editActive ? this.GrNo : "");
    this.grievanceForm.controls['TeacherId'].setValue(this.staffInfoForm.value.staffId);
    this.grievanceForm.controls['SchoolKeyId'].setValue(this.school_id);
    this.grievanceForm.controls['BlkId'].setValue(this.blockid);
    let grievanceDateFormat = this.pipe.transform(this.grievanceForm.value.GrievanceDate, 'yyyy-MM-dd')
    this.grievanceForm.controls['GrievanceDate'].setValue(grievanceDateFormat);
    if (this.grievanceForm.valid) {
      if (this.editActive) {
        this.onSave();
      } else {
        this.onAlert(1, '');
      }
    }
    else {
      this.sharedService.validateAllFormFields(this.grievanceForm);
      this.alertService.error('Please Fill all the Required Fields');
    }
  }

  onSave() {
    var data = { "records": this.grievanceForm.value }
    this.grievanceService.saveStaffGrievance(data).subscribe(res => {
      if (res.dataStatus) {
        if (this.editActive) {
          this.pageid = 1;
          this.ionViewDidEnter();
          this.alertService.success(res.message);
        } else {
          if (res.Grno) {
            let grNo = "GR/" + "B" + (this.blockid.length == 3 ? (this.blockid + '/') :
              this.blockid.length == 2 ? ('0' + this.blockid + '/') : ('00' + this.blockid + '/')) + res.Grno;
            this.onAlert(2, grNo);
            this.grievanceService.sendOTP(grNo, this.grievanceForm.value.MblNo);
          }
          else {
            this.onValidateGrievanceForm();
          }
        }
      }
      else {
        this.alertService.error(res.message);
      }
    })
  }

  onAlert(id, GrNo) {
    this.grievanceService.onAlert(id, this.language, GrNo).then((data) => {
      debugger
      if(data.data.values){
        if (data.data.values.length > 0) {
            this.onSave();
        }
        else {
          this.onAlert(1, '')
          this.alertService.error('Please Select Checkbox')
        }
      } else {
        this.pageid = 1;
        this.ionViewDidEnter();
      }
    });
  }

  // ------ Update Grievance Status ----------//

  updateGrievanceStatus(id, item) {
    var data = {
      "records": {
        "IndexId": item.IndexId,
        "GrievanceStatus": id,
        "Flag": 1
      }
    }
    this.grievanceService.saveStaffGrievance(data).subscribe(res => {
      if (res.dataStatus) {
        this.ionViewDidEnter();
      }
    });
  }

  // --------Saved Grievance Data -----------//

  getSavedGrievanceData() {
    this.grievanceList = [];
    this.grievanceListCopy = [];
    this.grievanceService.getStaffGrievance(this.teacherId).subscribe(res => {
      if (res.dataStatus) {
        this.noData = false;
        if (res.result.length > 0) {
          res.result.sort((a, b) => Date.parse(b.GrievanceDate) - Date.parse(a.GrievanceDate));
          res.result.map((x, i) => {
            this.grievanceList.push(x);
            this.grievanceList[i].GrievanceTypeText = this.grievanceTypeLists.filter(a => a.value == x.GrievanceType)[0].label;
            this.grievanceList[i].GrievanceCategoryText = this.grievanceCategoryLists.filter(a => a.value == x.GrievanceCategory)[0].label;
            this.grievanceList[i].GrievanceStatusText = this.statusList.filter(a => a.value == x.GrievanceStatus)[0].label;
            this.grievanceList[i].GrNo = "GR/" + "B" + (this.blockid.length == 3 ? (this.blockid + '/') :
              this.blockid.length == 2 ? ('0' + this.blockid + '/') : ('00' + this.blockid + '/')) + x.GrNo;
            this.grievanceList[i].dateFormat = this.pipe.transform(this.grievanceList[i].GrievanceDate, 'dd-MM-yyyy');
          });
          this.grievanceListCopy = [];
          this.grievanceList.filter(a => a.grievanceStatus != '');
          this.sharedService.unique(this.grievanceList, ['GrNo'])
          this.grievanceListCopy.push(this.grievanceList)
        }
      }
      else {
        this.noData = true;
        this.pageid == 2
      }
    })
  }

  // ----- Edit Icon ----------------//

  onEdit(list, index, id) {
    this.viewDoc1 = list[index].ResolveDoc1;
    this.viewDoc2 = list[index].ResolveDoc2;
    this.viewDoc3 = list[index].ResolveDoc3;
    this.grievanceStatusValue = list[index].GrievanceStatus;
    this.editId = id;
    this.IndexId = list[index].IndexId;
    this.GrNo = list[index].GrNo;
    if (list[index].MblNo) {
      this.grievanceForm.controls['MblNo'].setValue(list[index].MblNo);
    }
    this.editActive = true;
    this.staffInfoForm.patchValue(list[index]);
    this.grievanceForm.patchValue(list[index]);
    this.documentArr = [];
    this.grievanceForm.value.GrievanceDoc1 ? this.documentArr.push('GrievanceDoc1') : '';
    this.grievanceForm.value.GrievanceDoc2 ? this.documentArr.push('GrievanceDoc2') : '';
    this.grievanceForm.value.GrievanceDoc3 ? this.documentArr.push('GrievanceDoc3') : '';
    this.grievanceForm.value.GrievanceDoc4 ? this.documentArr.push('GrievanceDoc4') : '';
    this.grievanceForm.value.GrievanceDoc5 ? this.documentArr.push('GrievanceDoc5') : '';
    let issueList = (this.language == 'English') ? this.Lists.issues : this.Lists.issuesTamilList;
    this.issuesList = issueList.filter(i => i.type == this.grievanceForm.value.GrievanceCategory);
    this.pageid = 2;
    this.calculatePendingDays(this.grievanceForm.value.GrievanceDate)
  }

  // ----- Language Toggle Change ---------//

  onToggle(event) {
      this.language = event ? 'தமிழ்' : 'English';
      this.langJsonChange();
      let uniquegrievanceList: any[] = this.sharedService.unique(this.grievanceList, ['GrNo'])
      this.grievanceList = [];
      if (uniquegrievanceList.length > 0) {
        uniquegrievanceList.sort((a, b) => Date.parse(b.GrievanceDate) - Date.parse(a.GrievanceDate));
        uniquegrievanceList.map((x, i) => {
          this.grievanceList.push(x);
          this.grievanceList[i].GrievanceTypeText = this.grievanceTypeLists.filter(a => a.value == x.GrievanceType)[0].label;
          this.grievanceList[i].GrievanceCategoryText = this.grievanceCategoryLists.filter(a => a.value == x.GrievanceCategory)[0].label;
          this.grievanceList[i].GrievanceStatusText = this.statusList.filter(a => a.value == x.GrievanceStatus)[0].label;
        });
        this.grievanceListCopy = [];
        this.grievanceListCopy.push(this.grievanceList)
      }
    }

    onNavigateBack() {
      this.editActive = false;
      if (this.pageid == 2) {
        this.pageid = 1;
        this.ionViewDidEnter();
      } else {
        this.onToggle(true);
        this.router.navigate(['tabs/dashboard']);
      }
    }
  }
